test('rapid automatic filter changes preserve drafts and propagate the latest selection', async () => {
  const handlers = {};
  const hidden = [{ name: 'filter', value: 'All' }, { name: 'priorityFilter', value: 'All' }];
  const drafts = { search: 'Hit', dueFrom: '2025-01-01', dueThrough: '2025-12-31' };
  const selected = { filter: 'All', priorityFilter: 'All' };
  const requests = [];
  const replacements = [];
  const locations = [];
  const form = { method: 'get', action: 'http://localhost/projects/1' };
  const results = { replaceChildren: (...children) => replacements.push(children) };
  const source = await readFile(new URL('../public/app.js', import.meta.url), 'utf8');
  runInNewContext(source, {
    document: {
      addEventListener: (name, handler) => { handlers[name] = handler; },
      querySelector: () => results,
      querySelectorAll: () => hidden,
    },
    URL, URLSearchParams, AbortController,
    FormData: class { constructor() { return Object.entries({ ...selected, search: '' })[Symbol.iterator](); } },
    history: { replaceState: (_state, _title, url) => locations.push(String(url)) },
    location: { assign: () => assert.fail('Unexpected fallback navigation') },
    DOMParser: class { parseFromString(html) { return { querySelector: () => ({ childNodes: [html] }) }; } },
    fetch: (url, options) => new Promise((resolve) => requests.push({ url, options, resolve })),
  });
  const change = (name, value) => {
    selected[name] = value;
    return handlers.change({ target: { name, value, form, matches: () => true } });
  };
  const first = change('filter', 'Deleted');
  const second = change('priorityFilter', 'High');
  assert.equal(hidden[0].value, 'Deleted');
  assert.equal(hidden[1].value, 'High');
  assert.equal(requests[0].options.signal.aborted, true);
  assert.match(locations[1], /filter=Deleted&priorityFilter=High/);
  requests[1].resolve({ ok: true, text: async () => 'latest rows' });
  await second;
  requests[0].resolve({ ok: true, text: async () => 'stale rows' });
  await first;
  assert.deepEqual(replacements, [['latest rows']]);
  assert.deepEqual(drafts, { search: 'Hit', dueFrom: '2025-01-01', dueThrough: '2025-12-31' });

  const third = change('filter', 'All');
  handlers.submit();
  assert.equal(requests[2].options.signal.aborted, true);
  requests[2].resolve({ ok: true, text: async () => 'discarded rows' });
  await third;
  assert.equal(replacements.length, 1);
});

import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { test } from 'node:test';
import { DatabaseSync } from 'node:sqlite';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let stderr = '';
  child.stderr.on('data', (chunk) => { stderr += chunk; });
  const baseUrl = await new Promise((resolve, reject) => {
    let output = '';
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) resolve(`http://127.0.0.1:${match[1]}`);
    });
    child.once('error', reject);
    child.once('exit', (code) => reject(new Error(`Server exited (${code}): ${stderr}`)));
  });
  return {
    baseUrl,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

async function create(baseUrl, name) {
  return fetch(`${baseUrl}/projects`, {
    method: 'POST',
    body: new URLSearchParams({ name }),
    redirect: 'manual',
  });
}

async function post(baseUrl, path, fields) {
  return fetch(`${baseUrl}${path}`, {
    method: 'POST', body: new URLSearchParams(fields), redirect: 'manual',
  });
}

function taskRows(html) {
  return [...html.matchAll(/<li data-testid="task-row">([\s\S]*?)<\/li>/g)].map((match) => ({
    title: match[1].match(/<span>(.*?)<\/span>/s)[1],
    path: match[1].match(/action="(.*?)"/)[1],
    completed: / checked/.test(match[1]),
  }));
}

function projectSummaries(html) {
  return [...html.matchAll(/data-testid="project-summary">(.*?)<\/span>/g)].map((match) => match[1]);
}

function projectRows(html) {
  return [...html.matchAll(/<li data-testid="project-row">([\s\S]*?)<\/li>/g)].map((match) => ({
    name: match[1].match(/<span>(.*?)<\/span>/s)[1],
    path: match[1].match(/action="(.*?)"/)[1],
  }));
}

function priorityControls(html) {
  return [...html.matchAll(/<select id="task-priority-\d+"[^>]*>([\s\S]*?)<\/select>/g)].map((match) => ({
    disabled: / disabled/.test(match[0]),
    options: [...match[1].matchAll(/<option(?: selected)?>(.*?)<\/option>/g)].map((option) => option[1]),
    selected: match[1].match(/<option selected>(.*?)<\/option>/)[1],
  }));
}

function directoryRows(html) {
  return [...html.matchAll(/<li data-testid="directory-task-row">([\s\S]*?)<\/li>/g)].map((match) => {
    const field = (name) => match[1].match(new RegExp(`data-testid="directory-${name}"[^>]*>([\\s\\S]*?)<\\/span>`))[1];
    return { title: field('task-title'), project: field('project-name'),
      completion: field('task-completion'), priority: field('task-priority'),
      date: field('task-due-date'), notes: field('task-notes'), html: match[1] };
  });
}

